window.GRILE_QUESTION_SHARDS=window.GRILE_QUESTION_SHARDS||{};window.GRILE_QUESTION_SHARDS["shard-132"]=[{"id":"set2-6ek6beC4","fingerprint":"a2e636ea7bfe11d6","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CS","text":"Care este principalul criteriu utilizat în clasificarea Angle pentru anomalia de clasa a III-a și care este o limitare importantă a acestei metode?","options":[{"id":"A","text":"Utilizează ca referință dezvoltarea în exces a mandibulei, dar nu ia în considerare deficitul de dezvoltare a maxilarului."},{"id":"B","text":"Se bazează pe relațiile de ocluzie în sens sagital de la nivelul primilor molari permanenți, dar nu analizează modificările scheletice ale bazelor maxilare."},{"id":"C","text":"Se bazează pe mărimea mandibulei, împărțind anomaliile în cele cu dimensiune normală și cele cu dezvoltare în exces."},{"id":"D","text":"Se concentrează pe cauza anomaliei (osoasă, musculară, dentară), omițând însă poziția mandibulei în intercuspidare maximă."},{"id":"E","text":"Definește dezechilibrul complex între maxilar și mandibulă, incluzând compensarea dento-alveolară și a țesuturilor moi."}],"correct":["B"],"pages":[522],"source":"set-2"},{"id":"set2-poSOZkLy","fingerprint":"538df3496cd7bfde","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CS","text":"În clasificarea lui Tweed, ce caracterizează categoria A (pseudo-clasa a III-a) și categoria B (clasa a III-a scheletică)?","options":[{"id":"A","text":"Categoria A corespunde sindromului progenic fals, iar categoria B sindromului progenic adevărat din școala germană."},{"id":"B","text":"Categoria A este caracterizată de ocluzie inversă frontală, iar categoria B de o poziție mezializată a molarilor de 6 ani."},{"id":"C","text":"Categoria A este definită de o dimensiune normală a mandibulei, în timp ce categoria B implică o mandibulă dezvoltată în exces sau un maxilar subdezvoltat."},{"id":"D","text":"Categoria A se referă la o cauză musculară, iar categoria B la o cauză osoasă sau dentară a anomaliei."},{"id":"E","text":"Categoria A implică o conducere forțată a mandibulei, iar categoria B se datorează exclusiv macrognației mandibulare."}],"correct":["C"],"pages":[522],"source":"set-2"},{"id":"set2-WIuZsgbp","fingerprint":"b22b483d4587f91c","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CS","text":"Conform lui Moyers, care este mecanismul principal prin care se instalează o pseudo-clasă a III-a?","options":[{"id":"A","text":"Un deficit de dezvoltare a maxilarului superior, care creează un decalaj sagital negativ."},{"id":"B","text":"O conducere forțată de natură condiliană (articulară) care modifică traiectoria de închidere a mandibulei."},{"id":"C","text":"Modificări de ax ale dinților anteriori care duc la un angrenaj invers frontal."},{"id":"D","text":"Existența unui contact dentar prematur ce forțează mandibula într-o poziție anterioară printr-un reflex neuro-muscular dobândit."},{"id":"E","text":"Dezvoltarea în exces a mandibulei (macrognație), care duce la o poziționare anterioară structurală."}],"correct":["D"],"pages":[522],"source":"set-2"},{"id":"set2-GnCZ0DES","fingerprint":"7e787e4977ea97ec","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CS","text":"Care sunt cele două forme clinice ale sindromului progenic conform clasificării școlii germane (Kantorowicz, Korkhaus, modificată)?","options":[{"id":"A","text":"Anomalia de cauză osoasă și anomalia de cauză musculară."},{"id":"B","text":"Anomalia de clasa a III-a categoria A și anomalia de clasa a III-a categoria B."},{"id":"C","text":"Prognația mandibulară prin macrognație și pseudoprognația mandibulară."},{"id":"D","text":"Sindromul progenic adevărat și sindromul progenic fals."},{"id":"E","text":"Prognatismul mandibular adevărat și prognatismul mandibular funcțional."}],"correct":["D"],"pages":[522],"source":"set-2"},{"id":"set2-YVl4mTyi","fingerprint":"d60159e7f2dc35d2","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CS","text":"Ce caracterizează sindromul progenic fals în viziunea școlii germane?","options":[{"id":"A","text":"O dezvoltare în exces a mandibulei."},{"id":"B","text":"O poziție mezializată a molarilor de 6 ani, fără referire la bazele osoase."},{"id":"C","text":"O dimensiune normală a mandibulei, fiind echivalent cu pseudo-clasa a III-a Tweed."},{"id":"D","text":"Un deficit de dezvoltare a maxilarului sau o poziționare anterioară a mandibulei prin conducere forțată."},{"id":"E","text":"O deplasare mandibulară determinată de un reflex neuro-muscular dobândit."}],"correct":["D"],"pages":[522],"source":"set-2"},{"id":"set2-9hhn6jhA","fingerprint":"dbdbe44c65e02b8b","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"Care dintre următoarele entități sunt considerate forme de pseudoprognație mandibulară în clasificarea lui Boboc?","options":[{"id":"A","text":"Cea determinată de relații intermaxilare anormale, precum conducerea condiliană sau cuspidiană."},{"id":"B","text":"Cea care are la bază macrognația mandibulară."},{"id":"C","text":"Cea cauzată de deficitul de dezvoltare a maxilarului superior."},{"id":"D","text":"Cea definită de poziția mezializată a molarilor de 6 ani."},{"id":"E","text":"Cea produsă de modificări de ax ale dinților anteriori (ocluzie inversă frontală)."}],"correct":["A","C","E"],"pages":[522],"source":"set-2"},{"id":"set2-p_pnLkNx","fingerprint":"cdf9079ffc18a1f1","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CS","text":"Ce test este menționat ca fiind foarte util pentru diagnosticul diferențial între prognatismul mandibular adevărat și cel funcțional?","options":[{"id":"A","text":"Clasificarea anomaliilor în funcție de etiologie (osoasă, musculară, dentară)."},{"id":"B","text":"Evaluarea topografică a dezechilibrului bazelor osoase."},{"id":"C","text":"Identificarea contactelor dentare premature."},{"id":"D","text":"Testul de retropulsie a mandibulei."},{"id":"E","text":"Analiza ocluziei la nivelul primilor molari permanenți."}],"correct":["D"],"pages":[522],"source":"set-2"},{"id":"set2-CeT9Gmac","fingerprint":"b643cc4f8beb1755","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CS","text":"Ce definește prognația mandibulară anatomică sau adevărată?","options":[{"id":"A","text":"Creșterea în exces a mandibulei, cunoscută și ca macrognație."},{"id":"B","text":"Un deficit de dezvoltare a maxilarului superior."},{"id":"C","text":"Poziționarea sau deplasarea anterioară a mandibulei."},{"id":"D","text":"Modificări de ax ale dinților anteriori care conduc la ocluzie inversă."},{"id":"E","text":"Un reflex neuro-muscular dobândit ca urmare a unui contact dentar prematur."}],"correct":["A"],"pages":[522],"source":"set-2"},{"id":"set2-IRNnhzzp","fingerprint":"0feac70d711eb0d7","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CS","text":"Care este distincția fundamentală între anomaliile de clasa a III-a de formă dentară și cele de formă scheletală?","options":[{"id":"A","text":"Forma dentară implică doar substratul dentar, în timp ce forma scheletală afectează atât dinții, cât și oasele maxilare, având implicații diferite asupra planului de tratament."},{"id":"B","text":"Ambele forme au aceeași abordare terapeutică, diferența constând doar în momentul debutului anomaliei."},{"id":"C","text":"Forma scheletală este mult mai frecventă la caucazieni, pe când cea dentară este specifică populației asiatice."},{"id":"D","text":"Forma scheletală este întotdeauna de natură ereditară, spre deosebire de forma dentară, care este cauzată exclusiv de factori locali."},{"id":"E","text":"Forma dentară se corectează spontan în dentiția permanentă, în timp ce forma scheletală necesită întotdeauna intervenție chirurgicală."}],"correct":["A"],"pages":[523],"source":"set-2"},{"id":"set2-F5Mf-TV4","fingerprint":"e84b3d2e572cc996","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"Care dintre următoarele afirmații referitoare la prevalența anomaliilor de clasa a III-a sunt corecte?","options":[{"id":"A","text":"La populația caucaziană, prevalența este de 1-4%."},{"id":"B","text":"Afro-americanii prezintă o prevalență ridicată, de 4-12%."},{"id":"C","text":"Prevalența globală a anomaliei de clasa a III-a este cea mai scăzută dintre toate clasele de anomalii."},{"id":"D","text":"Retrognația maxilară este cauza principală a sindromului progenic în aproximativ 60-70% dintre cazuri."},{"id":"E","text":"Incidența cea mai mare se observă în rândul populației asiatice, cu valori de 9-19% la coreeni."}],"correct":["A","C","E"],"pages":[523],"source":"set-2"},{"id":"set2-bAf-W0UY","fingerprint":"4e60c9429a7093f7","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CS","text":"În ce context clinic se întâlnește preponderent pseudoprognația mandibulară?","options":[{"id":"A","text":"Ca o consecință a hipotiroidiei în dentiția adultă."},{"id":"B","text":"În dentiția permanentă, ca urmare a acromegaliei adultului."},{"id":"C","text":"Exclusiv la membrii familiilor cu istoric de prognatism, precum dinastia Habsburgilor."},{"id":"D","text":"La populația caucaziană adultă, ca formă minoră de anomalie."},{"id":"E","text":"În dentiția temporară și mixtă la copiii cu vârste între 8 și 12 ani."}],"correct":["E"],"pages":[523],"source":"set-2"},{"id":"set2-F7HFxqmO","fingerprint":"716647175b3faaa9","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CS","text":"Ce rol joacă ereditatea în etiopatogenia prognatismului mandibular anatomic?","options":[{"id":"A","text":"Este relevantă doar în cazul populațiilor asiatice, unde prevalența este maximă."},{"id":"B","text":"Se manifestă exclusiv printr-un mod de transmitere autozomal recesiv."},{"id":"C","text":"Rolul său este pur teoretic și nu poate fi observat clinic în cadrul familiilor."},{"id":"D","text":"Are un impact semnificativ, moștenirea genetică familială influențând puternic dimensiunile scheletului facial."},{"id":"E","text":"Este un factor minor, influența sa fiind depășită de tulburările neuroendocrine."}],"correct":["D"],"pages":[523],"source":"set-2"},{"id":"set2-tB3MH70O","fingerprint":"34c90492bb1d6792","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"Care dintre următoarele tulburări neuroendocrine sunt menționate ca factori etiologici pentru prognatismul mandibular anatomic?","options":[{"id":"A","text":"Hipersecreția hormonului de creștere hipofizar, care determină creșterea excesivă a mandibulei."},{"id":"B","text":"Hipotiroidia, care poate cauza o creștere exagerată a mandibulei printr-un mecanism indirect."},{"id":"C","text":"Hipertiroidia, prin accelerarea generalizată a proceselor de creștere osoasă."},{"id":"D","text":"Insuficiența suprarenală, care afectează metabolismul osos al condilului mandibular."},{"id":"E","text":"Hiposecreția hormonului de creștere, care duce la o creștere compensatorie a mandibulei."}],"correct":["A","B"],"pages":[523],"source":"set-2"},{"id":"set2-OhAXo-oS","fingerprint":"a1930070c90900b2","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CS","text":"Cum este descrisă etiologia anomaliei de clasa a III-a?","options":[{"id":"A","text":"Strict dependentă de factori locali, precum obiceiurile vicioase și poziția limbii."},{"id":"B","text":"Determinată de un singur factor dominant, specific fiecărui subtip clinic."},{"id":"C","text":"În principal legată de tulburări endocrine apărute în perioada de creștere."},{"id":"D","text":"Multifactorială, fiind rezultatul interacțiunii dintre factorii generali și cei locali."},{"id":"E","text":"Exclusiv genetică, cu transmitere autozomal dominantă în majoritatea cazurilor."}],"correct":["D"],"pages":[523],"source":"set-2"},{"id":"set2-IyvCJ5Ww","fingerprint":"c0ab1b1e7573a116","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"Care dintre următoarele sindroame genetice se pot asocia cu prognatismul mandibular?","options":[{"id":"A","text":"Sindromul Gorlin"},{"id":"B","text":"Condro-distrofia fetală"},{"id":"C","text":"Sindromul progenic este asociat cu disfuncții neuropsihice, precum oligofrenia."},{"id":"D","text":"Sindromul Crouzon"},{"id":"E","text":"Sindromul alcoolic fetal"}],"correct":["A","B","D","E"],"pages":[524],"source":"set-2"},{"id":"set2-69z9aZqI","fingerprint":"af7c2575c9e9792a","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"Prin ce mecanisme o pseudoprognație se poate transforma într-o prognație adevărată?","options":[{"id":"A","text":"Prin moștenirea unui tip genetic de dezvoltare facială specific."},{"id":"B","text":"Prin prezența unor cicatrici rezultate în urma procedurilor chirurgicale."},{"id":"C","text":"Prin prezența unor disfuncții neuropsihice, cum ar fi oligofrenia."},{"id":"D","text":"Prin modificări la nivelul articulației temporo-mandibulare."},{"id":"E","text":"Prin modificarea direcțiilor de transmitere a forțelor în timpul funcțiilor aparatului dento-maxilar."}],"correct":["D","E"],"pages":[524],"source":"set-2"},{"id":"set2-oqXlc2SD","fingerprint":"c7f1b81321b6bf39","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"Care dintre următorii factori etiopatogenici sunt implicați în pseudoprogmatismul prin retrognatism maxilar?","options":[{"id":"A","text":"Macroglosia."},{"id":"B","text":"Deglutiția atipică cu presiune pe incisivii inferiori."},{"id":"C","text":"Obstrucțiile căilor respiratorii superioare, precum vegetațiile adenoide."},{"id":"D","text":"Ticurile de propulsie a mandibulei."},{"id":"E","text":"Absența mugurilor incisivilor laterali superiori."}],"correct":["C","E"],"pages":[524],"source":"set-2"},{"id":"set2-KXQA6uCa","fingerprint":"7a3d4e6b2fdeb6f1","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"Ce factori pot determina pseudoprogmatismul mandibular prin poziționarea sau deplasarea anterioară a mandibulei?","options":[{"id":"A","text":"Ocluzia inversă frontală."},{"id":"B","text":"Mărirea de volum a limbii (macroglosia)."},{"id":"C","text":"Hiperactivitatea musculaturii circumorale."},{"id":"D","text":"Lipsa abraziunii fiziologice a caninilor temporari inferiori."},{"id":"E","text":"Deglutiția atipică cu poziționarea limbii în interiorul arcului mandibular."}],"correct":["B","D","E"],"pages":[524],"source":"set-2"},{"id":"set2-h4bC32rx","fingerprint":"f7f270f2d307dca2","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"În contextul despicăturilor labio-maxilo-palatine, care sunt mecanismele ce contribuie la hipodezvoltarea maxilară și asocierea cu sindromul progenic?","options":[{"id":"A","text":"Hipertrofia musculară generalizată."},{"id":"B","text":"Excesul de creștere mandibulară primar."},{"id":"C","text":"Deformarea intrinsecă."},{"id":"D","text":"Cicatricile rezultate în urma procedurilor chirurgicale de corectare."},{"id":"E","text":"Tipul genetic moștenit de dezvoltare facială."}],"correct":["C","D","E"],"pages":[524],"source":"set-2"},{"id":"set2-psQdDuTI","fingerprint":"08f70fc23ea85bbb","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CS","text":"Care dintre următoarele afirmații descrie corect o cauză a pseudoprogmatismului prin retrognatism maxilar?","options":[{"id":"A","text":"Mărirea de volum a limbii inhibă dezvoltarea sagitală a osului maxilar."},{"id":"B","text":"Respirația orală duce la ticuri de propulsie a mandibulei."},{"id":"C","text":"Contactele premature cauzate de obturații în exces blochează dezvoltarea anterioară a maxilarului."},{"id":"D","text":"Angrenajul invers poate frâna creșterea antero-posterioară a maxilarului."},{"id":"E","text":"Atitudinile posturale nocturne, precum dormitul cu capul în hiperflexie, determină subdezvoltarea maxilarului."}],"correct":["D"],"pages":[524],"source":"set-2"},{"id":"set2-OKH_bmYq","fingerprint":"dad2b1b0994503cc","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CS","text":"Ce semn clinic specific poate fi evidențiat pe limbă în cazurile de macroglosie care determină o poziție anterioară a mandibulei?","options":[{"id":"A","text":"Hipertrofia papilelor gustative."},{"id":"B","text":"O mobilitate redusă a vârfului limbii."},{"id":"C","text":"Prezența unor fisuri adânci pe fața dorsală."},{"id":"D","text":"Amprenta dinților laterali pe marginile limbii."},{"id":"E","text":"O culoare palidă a mucoasei linguale."}],"correct":["D"],"pages":[524],"source":"set-2"},{"id":"set2-U-HXtOEe","fingerprint":"ad6e80c192af49af","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"Care dintre următorii pot fi factori etiologici în pseudoprognatismul mandibular prin modificarea axelor dentare?","options":[{"id":"A","text":"Cicatricile posttraumatice care pot devia dintele în erupția sa."},{"id":"B","text":"Formarea mugurilor incisivilor superiori în poziție palatinală."},{"id":"C","text":"Tulburări ale procesului de erupție, cum ar fi erupția simultană a incisivilor superiori și inferiori."},{"id":"D","text":"Dezvoltarea insuficientă a mandibulei în raport cu maxilarul."},{"id":"E","text":"Obiceiurile vicioase, precum succiunea degetului cu tracțiune pe incisivii inferiori."}],"correct":["A","B","E"],"pages":[525],"source":"set-2"},{"id":"set2-oqQru02X","fingerprint":"d6b6749f4ba9a76a","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CS","text":"În prognatismul mandibular anatomic, ce valoare poate atinge unghiul mandibular?","options":[{"id":"A","text":"Se menține în limite normale, în jur de 120-125°."},{"id":"B","text":"Prezintă valori similare cu cele din sindromul progenic prin deficit de dezvoltare a maxilarului."},{"id":"C","text":"Poate ajunge la valori de 140-145°."},{"id":"D","text":"Poate ajunge la valori de 100-105°."},{"id":"E","text":"Scade sub 110°, devenind mai ascuțit."}],"correct":["C"],"pages":[525],"source":"set-2"},{"id":"set2-UxqP-w6u","fingerprint":"9984ebe0658949e7","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"Care dintre următoarele semne clinice faciale sunt caracteristice prognatismului mandibular anatomic?","options":[{"id":"A","text":"Șanțul labio-mentonier șters."},{"id":"B","text":"Buza superioară proeminentă anterior (procheilie superioară)."},{"id":"C","text":"Etajul inferior al feței mărit."},{"id":"D","text":"Profilul facial concav."},{"id":"E","text":"Punctul gnathion situat pe planul orbito-frontal (planul Simon)."}],"correct":["A","C","D"],"pages":[525],"source":"set-2"},{"id":"set2-NlCVtuwJ","fingerprint":"d886c4cb5d6d073b","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CS","text":"În sindromul progenic prin deficit de dezvoltare a maxilarului, care este poziția punctului gnathion?","options":[{"id":"A","text":"Este situat anterior de planul orbito-frontal (planul Simon)."},{"id":"B","text":"Este situat pe planul orbito-frontal (planul Simon)."},{"id":"C","text":"Poziția sa nu este relevantă pentru diagnostic."},{"id":"D","text":"Este situat pe planul nazo-frontal (planul Dreyfuss)."},{"id":"E","text":"Este situat posterior de planul orbito-frontal (planul Simon)."}],"correct":["B"],"pages":[525],"source":"set-2"},{"id":"set2-hQgIwdXq","fingerprint":"7d1d309b49e510c0","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"Care dintre următoarele afirmații descriu corect semnele clinice faciale în sindromul progenic prin deficit de dezvoltare a maxilarului?","options":[{"id":"A","text":"Profilul este concav, dar cu valori mai mici decât în cazul prognatismului mandibular anatomic."},{"id":"B","text":"Mentonul este proeminent anterior, depășind planul nazo-frontal."},{"id":"C","text":"Treapta buzelor este inversată, în special prin retrocheilie superioară."},{"id":"D","text":"Punctul subnasale este situat posterior de planul nazofrontal."},{"id":"E","text":"Unghiul mandibular este mărit, ajungând la valori de 140-145°."}],"correct":["A","C","D"],"pages":[525],"source":"set-2"},{"id":"set2-w3lp8yDh","fingerprint":"d924a22cd0e8546a","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"Care sunt semnele faciale caracteristice pseudo-prognatismului mandibular prin retrognatism maxilar?","options":[{"id":"A","text":"Dezvoltarea insuficientă a maxilarului superior."},{"id":"B","text":"Profilul este drept sau ușor concav."},{"id":"C","text":"Etajul mijlociu al figurii poate fi micșorat."},{"id":"D","text":"Etajul inferior este normal sau ușor mărit."},{"id":"E","text":"Unghiul mandibular este ușor modificat."}],"correct":["A","C","E"],"pages":[526],"source":"set-2"},{"id":"set2-BQYwk7i5","fingerprint":"0fb3cd55a4d08c57","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"Ce semne clinice faciale sunt specifice pseudo-prognatismului mandibular prin poziționare anterioară (forma funcțională)?","options":[{"id":"A","text":"Punctul subnasale este situat pe planul Dreyfuss."},{"id":"B","text":"Etajul inferior este normal sau ușor mărit."},{"id":"C","text":"Punctul gnathion este situat pe planul Simon."},{"id":"D","text":"Retrocheilie superioară."},{"id":"E","text":"Profilul este drept sau ușor concav."}],"correct":["A","B","E"],"pages":[526],"source":"set-2"},{"id":"set2-V66y9Gjp","fingerprint":"68dfeb23610582ef","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"În cazul pseudo-prognatismului mandibular prin modificări ale axului dinților frontali, care dintre următoarele afirmații sunt corecte?","options":[{"id":"A","text":"Retrocheilia superioară se corelează cu retrodenția frontală superioară."},{"id":"B","text":"Treapta buzelor este normală."},{"id":"C","text":"Etajele feței sunt în limite normale."},{"id":"D","text":"Punctul gnathion este situat anterior față de planul Simon."},{"id":"E","text":"Unghiul mandibular este normal."}],"correct":["A","C","E"],"pages":[526],"source":"set-2"},{"id":"set2-ZJcV9iFP","fingerprint":"b7863afd1bb1808c","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"Care sunt semnele clinice intraorale ale prognatismului mandibular adevărat, rezultat din creșterea în exces a mandibulei?","options":[{"id":"A","text":"O linguo-înclinare compensatorie a întregii arcade dento-alveolare inferioare."},{"id":"B","text":"Prezența înghesuirilor dentare la nivelul arcadei inferioare."},{"id":"C","text":"Decalaj de erupție, cu erupția dinților inferiori cu mult timp înaintea celor superiori."},{"id":"D","text":"Mărirea arcadei alveolo-dentare inferioare, atât sagital, cât și transversal."},{"id":"E","text":"Raport interarcadic de tip progen vizibil doar în dentiția permanentă."}],"correct":["A","C","D"],"pages":[526],"source":"set-2"},{"id":"set2-AFomD4KV","fingerprint":"2f750898ceec197b","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CS","text":"Ce elemente clinice indică severitatea unui prognatism mandibular adevărat?","options":[{"id":"A","text":"Asocierea cu vestibulo-înclinarea frontalilor superiori."},{"id":"B","text":"Decalajul de erupție între arcadele dentare."},{"id":"C","text":"Gradul de mezializare al rapoartelor din zona molară și valoarea inocluziei sagitale inverse."},{"id":"D","text":"Gradul de linguo-înclinare compensatorie a frontalilor inferiori."},{"id":"E","text":"Prezența spațierilor între caninul și primul molar temporar inferior."}],"correct":["C"],"pages":[526],"source":"set-2"},{"id":"set2-tzf7DyGd","fingerprint":"ac20e9e89054cf56","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CS","text":"Care asociere de semne ocluzale caracterizează forma cea mai gravă de prognație mandibulară adevărată?","options":[{"id":"A","text":"Incluzie sagitală mare și raport interarcadic de tip progen."},{"id":"B","text":"Ocluzie inversă totală, inocluzie sagitală și ocluzie deschisă."},{"id":"C","text":"Rapoarte de ocluzie accentuate mezializate și spațieri interdentare inferioare."},{"id":"D","text":"Ocluzie deschisă și vestibulo-înclinarea accentuată a frontalilor superiori."},{"id":"E","text":"Ocluzie inversă totală asociată cu linguo-înclinarea accentuată a frontalilor inferiori."}],"correct":["B"],"pages":[526],"source":"set-2"},{"id":"set2-URv26WrO","fingerprint":"17ed5e2450d53699","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"Care dintre următoarele semne clinice intraorale sunt caracteristice pseudoprognatismului mandibular prin retrognatism maxilar?","options":[{"id":"A","text":"Deficit de dezvoltare al arcadei superioare în plan sagital și transversal."},{"id":"B","text":"Lipsa diastemizării fiziologice sau spațieri mici între dinții temporari la arcada superioară."},{"id":"C","text":"Lipsa abraziunii fiziologice în dentiția temporară, în special la caninii inferiori."},{"id":"D","text":"Retracții gingivale la nivelul dinților frontali inferiori cauzate de trauma ocluzală."},{"id":"E","text":"Vestibulo-înclinarea marcată a frontalilor superiori, cu caracter compensatoriu."}],"correct":["A","B","E"],"pages":[527],"source":"set-2"},{"id":"set2-MybYN0Yo","fingerprint":"f791dc27b952ba6c","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"În contextul unui pseudoprognatism mandibular prin poziționare anterioară, ce factori pot contribui la această anomalie?","options":[{"id":"A","text":"Deficitul de spațiu pe arcadă care duce la malpoziții dentare."},{"id":"B","text":"Obturații ocluzale în exces."},{"id":"C","text":"Retrodenția frontală superioară."},{"id":"D","text":"Lipsa abraziunii fiziologice în dentiția temporară, în special la caninii inferiori."},{"id":"E","text":"Un fren lingual foarte scurt care determină o poziționare joasă a limbii."}],"correct":["B","D","E"],"pages":[527],"source":"set-2"},{"id":"set2-8rVBLYuj","fingerprint":"e051c708d78b498a","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"Ce modificări specifice sunt întâlnite în pseudoprognatismul mandibular cauzat de modificarea axelor dinților frontali?","options":[{"id":"A","text":"Retrodenția frontală superioară, uneori cu suprafețe de abraziune pe fața vestibulară."},{"id":"B","text":"Vestibularizarea frontalilor inferiori (prodenție frontală inferioară)."},{"id":"C","text":"Vestibulo-înclinarea compensatorie a frontalilor superiori."},{"id":"D","text":"Lipsa diastemizării fiziologice la arcada superioară."},{"id":"E","text":"Retracții gingivale la nivelul dinților frontali inferiori ca urmare a traumei ocluzale."}],"correct":["A","B","E"],"pages":[527],"source":"set-2"},{"id":"set2-CqBn09NQ","fingerprint":"42a5415c82bfb8cd","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CS","text":"În ce situație clinică testul de retropulsie a mandibulei este pozitiv?","options":[{"id":"A","text":"În pseudoprognatismul mandibular prin deficit de dezvoltare a maxilarului superior."},{"id":"B","text":"În pseudoprognatismul mandibular prin conducere cuspidiană."},{"id":"C","text":"În prognatismul mandibular anatomic."},{"id":"D","text":"În pseudoprognatismul mandibular cauzat de angrenaj invers."},{"id":"E","text":"În pseudoprognatismul mandibular prin poziționare anterioară de natură articulară (conducere condiliană)."}],"correct":["E"],"pages":[527],"source":"set-2"},{"id":"set2-laDe0CVq","fingerprint":"8c0efb12a0c7c6a5","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"Care dintre următoarele condiții se asociază cu un test de retropulsie a mandibulei negativ?","options":[{"id":"A","text":"Prognatismul mandibular anatomic."},{"id":"B","text":"Pseudoprognatismul mandibular prin conducere cuspidiană."},{"id":"C","text":"Pseudoprognatismul mandibular produs prin ocluzie inversă frontală."},{"id":"D","text":"Pseudoprognatismul mandibular prin conducere condiliană."},{"id":"E","text":"Pseudoprognatismul mandibular prin deficit de dezvoltare a maxilarului superior."}],"correct":["A","C","E"],"pages":[527],"source":"set-2"},{"id":"set2-pF08m3xm","fingerprint":"f92763f84cd59b3c","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CS","text":"Care este o caracteristică a ocluziei în plan sagital, în cazul pseudoprognatismului mandibular prin retrognatism maxilar?","options":[{"id":"A","text":"Rapoarte distalizate severe."},{"id":"B","text":"Lipsa oricăror modificări ocluzale în plan sagital."},{"id":"C","text":"Rapoarte mezializate, dar cu valori mai mici comparativ cu prognația mandibulară adevărată."},{"id":"D","text":"Ocluzie cap la cap în zona laterală."},{"id":"E","text":"Rapoarte mezializate cu valori discrete, exclusiv asociate cu inocluzie sagitală."}],"correct":["C"],"pages":[527],"source":"set-2"},{"id":"set2-P0CYnniK","fingerprint":"56d8f70a53a30d96","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CS","text":"Ce examene radiologice sunt considerate indispensabile în diagnosticul și abordarea terapeutică a anomaliilor de clasa a III-a?","options":[{"id":"A","text":"Tomografia computerizată cu fascicul conic (CBCT)."},{"id":"B","text":"Doar radiografiile retroalveolare seriate."},{"id":"C","text":"Ortopantomograma și teleradiografia."},{"id":"D","text":"Doar ortopantomograma."},{"id":"E","text":"Radiografia cu film mușcat (bite-wing) și rezonanța magnetică nucleară (RMN)."}],"correct":["C"],"pages":[527],"source":"set-2"},{"id":"set2-msbZ7Yax","fingerprint":"051fdb471b391372","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"Care dintre următoarele semne radiologice observate pe o ortopantomogramă sunt caracteristice pentru pseudoprognatismul prin retrognatism maxilar?","options":[{"id":"A","text":"Prezența incluziilor dentare."},{"id":"B","text":"Spațieri mari între mugurii dinților permanenți succesionali."},{"id":"C","text":"Suprapunerea parțială sau totală a mugurilor dinților permanenți."},{"id":"D","text":"Migrări dentare și obturații ocluzale în exces."},{"id":"E","text":"Grad de dezvoltare avansat al dinților inferiori comparativ cu cei superiori."}],"correct":["A","C"],"pages":[528],"source":"set-2"},{"id":"set2-VWJY1a6Y","fingerprint":"9e4b6d7d633543e2","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CS","text":"În cazul unui pacient cu prognatism mandibular anatomic, ce valoare atinge unghiul mandibular pe o teleradiografie de profil?","options":[{"id":"A","text":"120-125°"},{"id":"B","text":"140-145°"},{"id":"C","text":"90-100°"},{"id":"D","text":"Sub 120°"},{"id":"E","text":"Rămâne în limite normale (120-125°)."}],"correct":["B"],"pages":[528],"source":"set-2"},{"id":"set2-avm2wkEk","fingerprint":"cbcbc821eb6632b5","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"Care dintre următoarele unghiuri evaluate pe teleradiografia de profil sunt mărite în prognatismul mandibular anatomic?","options":[{"id":"A","text":"Unghiul B al lui Schwarz"},{"id":"B","text":"Unghiul SNA"},{"id":"C","text":"Unghiul lui Tweed"},{"id":"D","text":"Unghiul ANB"},{"id":"E","text":"Unghiul SNB"}],"correct":["A","C","E"],"pages":[528],"source":"set-2"},{"id":"set2-Qeh4cIN2","fingerprint":"fec6bcd267b76b5c","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CS","text":"Ce modificare a unghiului SNA este caracteristică pentru pseudoprognatismul mandibular prin deficit de dezvoltare a maxilarului?","options":[{"id":"A","text":"Unghiul SNA este normal."},{"id":"B","text":"Unghiul SNA este micșorat."},{"id":"C","text":"Unghiul SNA este inversat."},{"id":"D","text":"Valoarea unghiului SNA nu este relevantă pentru acest diagnostic."},{"id":"E","text":"Unghiul SNA este mărit."}],"correct":["B"],"pages":[528],"source":"set-2"},{"id":"set2-SOhHt48T","fingerprint":"a1a8920777b386aa","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"În ce situație clinică punctul gnathion este situat anterior de planul orbito-frontal (planul Simon)?","options":[{"id":"A","text":"Într-o ocluzie normală, de Clasa I."},{"id":"B","text":"Prognatism mandibular anatomic."},{"id":"C","text":"Pseudoprognatism mandibular prin poziționarea/deplasarea anterioară a mandibulei."},{"id":"D","text":"Pseudoprognatism mandibular prin deficit de dezvoltare a maxilarului."},{"id":"E","text":"Pseudoprognatism mandibular prin modificări ale axelor dinților frontali."}],"correct":["B","C"],"pages":[528],"source":"set-2"},{"id":"set2-8TkEqj2p","fingerprint":"2f98eff0367fa355","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CS","text":"Ce indică o valoare mai mare de 70° a unghiului dintre incisivul central superior și planul bispinos?","options":[{"id":"A","text":"O dezvoltare deficitară a maxilarului."},{"id":"B","text":"Retrodenția incisivilor centrali superiori."},{"id":"C","text":"Prodenția incisivilor centrali superiori."},{"id":"D","text":"O dezvoltare excesivă a mandibulei."},{"id":"E","text":"O poziție normală a incisivilor."}],"correct":["B"],"pages":[528],"source":"set-2"},{"id":"set2-5jTixIIb","fingerprint":"dcafdbc2f3ecb2e4","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"Care dintre următoarele afirmații despre unghiul ANB sunt corecte în contextul anomaliilor de clasa a III-a?","options":[{"id":"A","text":"În pseudoprognatismul prin poziționare anterioară a mandibulei, unghiul ANB este mărit."},{"id":"B","text":"În pseudoprognatismul prin deficit maxilar, unghiul ANB rămâne în limite normale."},{"id":"C","text":"În prognatismul mandibular anatomic, unghiul ANB este micșorat sau raportul SNA/SNB este inversat."},{"id":"D","text":"În pseudoprognatismul prin poziționare anterioară a mandibulei, unghiul ANB este micșorat."},{"id":"E","text":"Valoarea normală a unghiului ANB este de +2° până la +4°."}],"correct":["C","D","E"],"pages":[528],"source":"set-2"},{"id":"set2-scXB9bKA","fingerprint":"c4afc768504a27c6","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CS","text":"Ce raport este utilizat pentru a evalua deficitul de dezvoltare a maxilarului pe o teleradiografie de profil?","options":[{"id":"A","text":"Raportul dintre baza maxilarului și baza mandibulei, care are o valoare normală de 1/2."},{"id":"B","text":"Raportul dintre lungimea ramului orizontal al mandibulei și distanța N-Se."},{"id":"C","text":"Raportul dintre distanța Spina Nazală Anterioară - Spina Nazală Posterioară și distanța N-Se."},{"id":"D","text":"Raportul dintre etajul inferior și etajul mijlociu al feței."},{"id":"E","text":"Raportul dintre unghiul SNA și unghiul SNB."}],"correct":["C"],"pages":[528],"source":"set-2"},{"id":"set2-o-i6Af2I","fingerprint":"3426b14e61184df5","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CS","text":"Care este valoarea normală a unghiului format de incisivii centrali inferiori cu planul bazal mandibular și ce indică o creștere a acestei valori?","options":[{"id":"A","text":"Valoarea normală este 90°+/-5°, iar o creștere indică retrodenția incisivilor inferiori."},{"id":"B","text":"Valoarea normală este 90°+/-5°, iar o creștere indică înghesuirea incisivilor inferiori."},{"id":"C","text":"Valoarea normală este 90°+/-5°, iar o creștere indică prodenția incisivilor inferiori."},{"id":"D","text":"Valoarea normală este 85°+/-5°, iar o creștere indică retrodenția incisivilor inferiori."},{"id":"E","text":"Valoarea normală este 95°+/-5°, iar o creștere este considerată în limite fiziologice."}],"correct":["C"],"pages":[529],"source":"set-2"},{"id":"set2-2Rjd9TKo","fingerprint":"c784624341c07190","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"Care dintre următoarele funcții ale aparatului dento-maxilar sunt afectate în anomalia de clasa a III-a?","options":[{"id":"A","text":"Funcția de deglutiție, prin comportamentul atipic al limbii."},{"id":"B","text":"Funcția fizionomică, prin modificările faciale caracteristice."},{"id":"C","text":"Funcția masticatorie, prin reducerea câmpului masticator."},{"id":"D","text":"Funcția fonetică, prin proiecția limbii între arcade în timpul vorbirii."},{"id":"E","text":"Funcția respiratorie, prin obstrucția căilor aeriene superioare."}],"correct":["A","B","C","D"],"pages":[529],"source":"set-2"},{"id":"set2-exZAvbc1","fingerprint":"637ea698bfc29211","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CS","text":"În care dintre următoarele situații anomalia de clasa a III-a are un prognostic favorabil, permițând corectarea spontană?","options":[{"id":"A","text":"În orice formă funcțională, indiferent de momentul intervenției terapeutice."},{"id":"B","text":"În forma clinică de pseudoprognatism prin conducere condiliană, în stadiu incipient."},{"id":"C","text":"În cazurile cu modificări morfologice deja prezente în dentiția mixtă."},{"id":"D","text":"În prognatismul mandibular anatomic, dacă tratamentul este instituit prepubertar."},{"id":"E","text":"La pacienții adulți unde cartilajul condilian și-a reluat activitatea."}],"correct":["B"],"pages":[529],"source":"set-2"},{"id":"set2-24l_u_S_","fingerprint":"ae2d58779709c207","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CS","text":"Ce caracteristică specifică a cartilajului condilian de creștere la pacienții cu anomalii de clasa a III-a contribuie la riscul de recidivă posttratament?","options":[{"id":"A","text":"Activitatea sa este complet independentă de factorii funcționali și se oprește ireversibil la 21 de ani."},{"id":"B","text":"Își încetează activitatea mult mai devreme decât în mod normal, în jurul vârstei de 16 ani."},{"id":"C","text":"Activitatea sa contribuie exclusiv la creșterea verticală, nu și la cea sagitală a mandibulei."},{"id":"D","text":"Poate rămâne activ o perioadă îndelungată sau își poate relua activitatea la vârsta adultă."},{"id":"E","text":"Activitatea sa este inhibată, ducând la o creștere insuficientă a mandibulei."}],"correct":["D"],"pages":[529],"source":"set-2"},{"id":"set2-h64qerRL","fingerprint":"164eaaabf5c5f222","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CS","text":"Care este evoluția tipică a anomaliilor de clasa a III-a scheletice în absența unui tratament ortodontic instituit devreme?","options":[{"id":"A","text":"Forma funcțională se transformă întotdeauna într-o formă dento-alveolară, nu scheletică."},{"id":"B","text":"Se transformă frecvent în anomalii de clasa a II-a în perioada adolescenței târzii."},{"id":"C","text":"Rămân stabile, fără modificări semnificative după instalarea în dentiția temporară."},{"id":"D","text":"Au tendința de a se corecta spontan în timpul puseului de creștere pubertar."},{"id":"E","text":"Au tendința să se agraveze în timp, cu o prelungire a perioadei de creștere a mandibulei."}],"correct":["E"],"pages":[529],"source":"set-2"},{"id":"set2-nvR4m8HZ","fingerprint":"ba83d49c1f7ae34b","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CS","text":"Conform studiilor, care este momentul optim pentru administrarea tratamentului ortopedic interceptiv pentru a obține un prognostic favorabil în anomaliile de clasa a III-a?","options":[{"id":"A","text":"În timpul puseului de creștere pubertar."},{"id":"B","text":"La vârsta adultă, după încetarea completă a creșterii mandibulare."},{"id":"C","text":"Înainte de puseul de creștere pubertar."},{"id":"D","text":"Oricând în perioada dentiției mixte, indiferent de stadiul de creștere."},{"id":"E","text":"După finalizarea erupției dentiției permanente."}],"correct":["C"],"pages":[529],"source":"set-2"},{"id":"set2--aMb6esY","fingerprint":"486f57b9321e4e21","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"Care dintre următoarele acțiuni fac parte din tratamentul profilactic și interceptiv al sindromului progenic?","options":[{"id":"A","text":"Supravegherea procesului de abraziune a caninilor temporari inferiori."},{"id":"B","text":"Ignorarea diastemizării fiziologice, deoarece nu are legătură cu anomaliile sagitale."},{"id":"C","text":"Prevenirea și corectarea obiceiului vicios de succiune a degetelor cu presiune pe incisivii inferiori."},{"id":"D","text":"Asigurarea unei poziții corecte a copilului în timpul somnului și alimentației."},{"id":"E","text":"Încurajarea ticului de avansare a mandibulei pentru a stimula creșterea."}],"correct":["A","C","D"],"pages":[529],"source":"set-2"},{"id":"set2-V8uwD96b","fingerprint":"7a55dfea07cf0a68","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CS","text":"Care este secvența temporală corectă a dezvoltării și agravării anomaliei de clasa a III-a?","options":[{"id":"A","text":"Tiparul scheletic se conturează prepubertar, iar modificările dentare și agravarea discrepanței scheletice au loc în perioada pubertară și post-pubertară."},{"id":"B","text":"Modificările dentare preced conturarea tiparului scheletic, care se definitivează abia la vârsta adultă."},{"id":"C","text":"Tiparul scheletic și agravarea discrepanței apar simultan, exclusiv în timpul puseului de creștere pubertar."},{"id":"D","text":"Tiparul scheletic se conturează post-pubertar, ca o consecință a modificărilor dentare apărute în dentiția mixtă."},{"id":"E","text":"Atât tiparul scheletic cât și agravarea au loc exclusiv în dentiția temporară, anomalia stabilizându-se ulterior."}],"correct":["A"],"pages":[529],"source":"set-2"},{"id":"set2-_ZYITNfc","fingerprint":"c6327103d2252787","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"Care dintre următoarele reprezintă măsuri specifice tratamentului profilactic și interceptiv al sindromului progenic?","options":[{"id":"A","text":"Realizarea saltului articular pentru corectarea relațiilor de ocluzie."},{"id":"B","text":"Stimularea dezvoltării maxilarului și frânarea creșterii mandibulare."},{"id":"C","text":"Supravegherea diastemizării fiziologice și a procesului de abraziune a dinților temporari."},{"id":"D","text":"Desființarea contactelor premature prin șlefuiri selective."},{"id":"E","text":"Corectarea obiceiurilor vicioase, precum ticul de avansare a mandibulei."}],"correct":["C","D","E"],"pages":[530],"source":"set-2"},{"id":"set2-peGzUBVA","fingerprint":"1b3ea7adfb596a70","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CS","text":"Care este principalul avantaj al instituirii tratamentului curativ pentru sindromul progenic într-un stadiu incipient?","options":[{"id":"A","text":"Permite modificarea tiparului de creștere mandibular, care este dictat genetic."},{"id":"B","text":"Anomalia este mai puțin gravă clinic, iar plasticitatea osoasă crescută asigură o eficiență sporită a aparatelor ortodontice."},{"id":"C","text":"Permite finalizarea completă a tratamentului înainte de instalarea puseului maxim de creștere pubertar."},{"id":"D","text":"Elimină necesitatea extracțiilor dentare și a aplicării menținătoarelor de spațiu."},{"id":"E","text":"Anulează riscul de recidivă, care este altfel foarte ridicat."}],"correct":["B"],"pages":[530],"source":"set-2"},{"id":"set2-oguTpNgf","fingerprint":"ca7990c488f54edf","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"Referitor la gestionarea creșterii în tratamentul anomaliilor de clasa a III-a, care dintre următoarele afirmații sunt adevărate?","options":[{"id":"A","text":"Radiografiile cefalometrice seriate ajută la determinarea opririi sau continuării creșterii faciale."},{"id":"B","text":"Se recomandă efectuarea tratamentului ortodontic la pacienții cu prognatism mandibular anatomic în perioada de creștere activă."},{"id":"C","text":"La pacienții cu prognatism mandibular anatomic, tratamentul ortodontic poate stopa complet creșterea mandibulei."},{"id":"D","text":"Tiparul de creștere facial poate fi modificat fundamental prin intervenții ortodontice precoce."},{"id":"E","text":"Tiparul de creștere mandibular original revine dacă terapia ortodontică este finalizată înainte de încetarea creșterii."}],"correct":["A","E"],"pages":[530],"source":"set-2"},{"id":"set2-IMyv4F7-","fingerprint":"49b93ed1e9b11b01","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CS","text":"Care dintre următorii factori NU este considerat un indicator de prognostic bun pentru terapia precoce la pacienții cu anomalii de clasa a III-a, conform listei dezvoltate de Turpin?","options":[{"id":"A","text":"O creștere condiliană simetrică."},{"id":"B","text":"Existența unui prognatism mandibular funcțional."},{"id":"C","text":"Prezența unui istoric familial de prognatism mandibular."},{"id":"D","text":"O discrepanță scheletică minimă."},{"id":"E","text":"Un tipar de creștere facial convergent."}],"correct":["C"],"pages":[530],"source":"set-2"},{"id":"set2-Vew6gdLb","fingerprint":"6ee9a29d926f8a04","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"Care sunt obiectivele terapeutice principale ale tratamentului curativ în sindromul progenic?","options":[{"id":"A","text":"Tratamentul precoce al leziunilor carioase și aplicarea menținătoarelor de spațiu."},{"id":"B","text":"Monitorizarea procesului de erupție a dinților și extracția dinților supranumerari."},{"id":"C","text":"Armonizarea echilibrului între arcade prin stimularea dezvoltării maxilarului și/sau limitarea creșterii mandibulare."},{"id":"D","text":"Contenția rezultatului tratamentului activ pentru a preveni recidiva."},{"id":"E","text":"Obținerea unor rapoarte de ocluzie funcționale și stabile, inclusiv a unei supraocluzii frontale pentru contenție naturală."}],"correct":["C","D","E"],"pages":[530],"source":"set-2"},{"id":"set2-qu-Du-bB","fingerprint":"50ef5aca6b18c0e6","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CS","text":"Ce metodă este utilizată pentru a evalua obiectiv dacă procesul de creștere facială a unui pacient s-a încheiat?","options":[{"id":"A","text":"Analiza istoricului familial de creștere."},{"id":"B","text":"Evaluarea gradului de abraziune a dinților temporari."},{"id":"C","text":"Realizarea de radiografii cefalometrice seriate."},{"id":"D","text":"Testarea plasticității osoase prin aplicarea de forțe ortodontice."},{"id":"E","text":"Observarea clinică a esteticii faciale."}],"correct":["C"],"pages":[530],"source":"set-2"},{"id":"set2-VQlpDe-p","fingerprint":"df50a69dfc247454","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"Care dintre următoarele sunt menționate ca tipuri de aparate utilizate în tratamentul ortodontic al sindromului progenic?","options":[{"id":"A","text":"Aparate mobilizabile, precum plăcile ortodontice."},{"id":"B","text":"Aparate funcționale."},{"id":"C","text":"Pelota mentonieră ca aparat de sine stătător."},{"id":"D","text":"Aparate fixe, cum ar fi disjunctorul și masca Delaire."},{"id":"E","text":"Exclusiv bărbița cu capelină, pentru toate anomaliile."}],"correct":["A","B","D"],"pages":[531],"source":"set-2"},{"id":"set2-L_lFs7sp","fingerprint":"f8f1c0763904d7de","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CS","text":"Care este considerat mijlocul terapeutic de elecție pentru limitarea, frânarea sau repoziționarea mandibulară?","options":[{"id":"A","text":"Disjunctorul"},{"id":"B","text":"Plăcile ortodontice"},{"id":"C","text":"Masca Delaire"},{"id":"D","text":"Bărbița cu capelină"},{"id":"E","text":"Intervenția chirurgicală unimaxilară"}],"correct":["D"],"pages":[531],"source":"set-2"},{"id":"set2-u1UjVFD7","fingerprint":"71b452bbee58599c","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"Ce caracteristici sunt asociate cu anomaliile severe de clasa a III-a care necesită tratament ortodontico-chirurgical?","options":[{"id":"A","text":"Posibilitatea corectării discrepanțelor scheletale exclusiv prin terapie ortodontică."},{"id":"B","text":"Prezența unor decalaje scheletale mandibulo-maxilare semnificative."},{"id":"C","text":"Intervenția chirurgicală este întotdeauna bimaxilară."},{"id":"D","text":"Formele clinice pot include prognatismul mandibular adevărat sau pseudoprognatismul prin retrognatism maxilar."},{"id":"E","text":"Sunt asociate exclusiv cu anomalii dento-maxilare în plan sagital."}],"correct":["B","D"],"pages":[531],"source":"set-2"},{"id":"set2-ZpMGu07O","fingerprint":"5d2f022c2c9a4e2b","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CS","text":"În ce situație clinică specifică este recomandată tracțiunea extraorală vertex-menton (bărbița cu capelină)?","options":[{"id":"A","text":"Doar în combinație cu masca Delaire, pentru a-i spori efectul."},{"id":"B","text":"În orice etapă de dentiție pentru limitarea creșterii maxilare."},{"id":"C","text":"Ca tratament unic în cazurile severe de clasa a III-a."},{"id":"D","text":"În dentiția permanentă pentru pacienții cu retrognatism maxilar."},{"id":"E","text":"În dentiția temporară pentru pacienții cu prognatism mandibular anatomic."}],"correct":["E"],"pages":[531],"source":"set-2"},{"id":"set2-455zbmqD","fingerprint":"efc6964645d3e434","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"Care dintre afirmațiile de mai jos referitoare la clasificarea și terminologia sindromului progenic sunt adevărate?","options":[{"id":"A","text":"Deplasarea mandibulară în poziție anterioară printr-un reflex neuro-muscular definește clasa a III-a adevărată în concepția lui Moyers."},{"id":"B","text":"În funcție de substratul anatomic implicat, anomaliile de clasa a III-a se pot subîmpărți în forme dentare și forme scheletale."},{"id":"C","text":"Tweed definește pseudo-clasa a III-a printr-o dimensiune normală a mandibulei în cadrul categoriei A."},{"id":"D","text":"Școala germană descrie sindromul progenic adevărat ca fiind caracterizat prin dezvoltarea în exces a mandibulei."},{"id":"E","text":"Clasificarea lui Angle se bazează pe analiza detaliată a bazelor osoase ale celor două maxilare."}],"correct":["B","C","D"],"pages":[522],"source":"set-2"},{"id":"set2-45xpvoTy","fingerprint":"527a73a423d997a3","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"Care dintre următoarele elemente epidemiologice și etiopatogenice sunt caracteristice sindromului progenic?","options":[{"id":"A","text":"Pseudoprognația mandibulară se manifestă preponderent în dentiția definitivă."},{"id":"B","text":"Prevalența anomaliei de clasa a III-a este cea mai ridicată la populația afro-americană."},{"id":"C","text":"Retrognația maxilară reprezintă cauza principală a afecțiunii în aproximativ 40% din cazuri."},{"id":"D","text":"Prevalența globală a anomaliei de clasa a III-a este cea mai scăzută dintre toate clasele de anomalii dento-maxilare."},{"id":"E","text":"Între 60-70% din ocluziile inverse anterioare la copiii de 8-12 ani reprezintă forme de pseudoprognație mandibulară."}],"correct":["C","D","E"],"pages":[522],"source":"set-2"},{"id":"set2-P7iAzZlX","fingerprint":"d5239fd0a01b827c","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CS","text":"Care este parametrul clinic specific recomandat pentru realizarea diagnosticului diferențial între prognatismul mandibular adevărat și cel funcțional?","options":[{"id":"A","text":"Poziția incisivilor superiori în raport cu planul de la Frankfurt."},{"id":"B","text":"Testul de retropulsie a mandibulei."},{"id":"C","text":"Gradul de subdezvoltare a maxilarului superior la inspecție."},{"id":"D","text":"Relația ocluzală a molarilor de 6 ani în plan transversal."},{"id":"E","text":"Contactul dentar prematur la nivelul fețelor ocluzale ale premolarilor."}],"correct":["B"],"pages":[522],"source":"set-2"},{"id":"set2-VdYDOCRq","fingerprint":"113b28439c14d82c","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"Cum descrie Boboc etiologia pseudoprognației mandibulare în cadrul subdiviziunilor sale?","options":[{"id":"A","text":"Prin deplasarea posterioară a mandibulei cauzată de un deficit articular."},{"id":"B","text":"Prin conducere condiliană sau cuspidiană care determină o deplasare anterioară a mandibulei."},{"id":"C","text":"Prin dezvoltarea în exces a mandibulei sub formă de macrognație."},{"id":"D","text":"Prin deficit de dezvoltare a maxilarului superior."},{"id":"E","text":"Prin modificări de ax ale dinților anteriori, manifestate prin ocluzie inversă frontală."}],"correct":["B","D","E"],"pages":[522],"source":"set-2"},{"id":"set2-FuoGf-nG","fingerprint":"3bbd020c6ab17d69","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"În evaluarea anomaliilor de clasa a III-a, ce factori au fost subliniați în mod specific în clasificarea propusă de Moyers?","options":[{"id":"A","text":"Criteriul de clasificare strict dentar, dependent de angrenajul primilor molari permanenți."},{"id":"B","text":"Importanța stabilirii poziției mandibulei în relație centrică sau în poziție anterioară în momentul intercuspidării maxime."},{"id":"C","text":"Forțarea mandibulei într-o poziție anterioară ca urmare a unui contact dentar prematur ce declanșează un reflex neuro-muscular."},{"id":"D","text":"Cauza etiologică a anomaliei, care poate fi osoasă, musculară sau dentară."},{"id":"E","text":"Stabilirea pseudo-clasei a III-a ca entitate a categoriei A, cu o dimensiune normală a mandibulei."}],"correct":["B","C","D"],"pages":[522],"source":"set-2"},{"id":"set2-I92TchYp","fingerprint":"2dad306fdb52fc70","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CS","text":"Care este mecanismul prin care hipotiroidia poate determina apariția creșterii exagerate a mandibulei?","options":[{"id":"A","text":"Stimulează hiperactivitatea musculaturii circumorale, creând un dezechilibru între grupele musculare externe și interne."},{"id":"B","text":"Declanșează transformarea directă a pseudoprognației în prognație adevărată prin modificarea direcțiilor de transmitere a forțelor."},{"id":"C","text":"Produce o hipersecreție secundară de hormon somatotrop care modifică forma condilului și a cavității glenoide."},{"id":"D","text":"Blochează dezvoltarea centrelor osteogenetice secundare maxilare, favorizând un deficit sagital de creștere."},{"id":"E","text":"Acționează printr-un mecanism indirect generat de poziția limbii în arcul mandibular sau de macroglosia asociată mixedemului juvenil."}],"correct":["E"],"pages":[523],"source":"set-2"},{"id":"set2-YMq2m6AY","fingerprint":"550b9ad70f9d2435","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"Care dintre următorii factori etiopatogenici sunt implicați în dezvoltarea pseudoprognatismului prin retrognatism maxilar?","options":[{"id":"A","text":"Mărirea de volum a limbii manifestată clinic prin apariția amprentei dinților laterali pe marginile sale."},{"id":"B","text":"Cicatricile postchirurgicale apărute în urma intervențiilor de corectare a despicăturilor labio-maxilo-palatine."},{"id":"C","text":"Absența mugurilor dentari la maxilar, care suprimă dezvoltarea centrelor osteogenetice secundare."},{"id":"D","text":"Obstrucțiile căilor respiratorii superioare de tipul vegetațiilor adenoide și amigdalelor hipertrofice."},{"id":"E","text":"Erupția vestibularizată a incisivilor inferiori însoțită de o erupție oralizată a incisivilor superiori."}],"correct":["B","C","D"],"pages":[524],"source":"set-2"},{"id":"set2-xX1_U65v","fingerprint":"a81acd117891f03d","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"Ce manifestări și asocieri clinice sunt specifice sindroamelor genetice caracterizate prin prognatism mandibular și o dezvoltare atipică a etajului mijlociu?","options":[{"id":"A","text":"Sindromul Gorlin asociază prognatismului mandibular o serie de anomalii vertebrale, osoase, cutanate, neurologice și oftalmice."},{"id":"B","text":"Sindromul Crouzon include în mod caracteristic hipertelorism, strabism, hiperplazie medio-facială și proeminență nazală."},{"id":"C","text":"Sindromul alcoolic fetal se manifestă clinic printr-o hiperdezvoltare marcată a etajului mijlociu al feței."},{"id":"D","text":"Condro-distrofia fetală se distinge printr-un maxilar retrudat, brahicefalie și o musculatură hipertrofiată."},{"id":"E","text":"Acromegalia juvenilă cauzează o retrudare severă și hipodezvoltare a cavității glenoide determinată exclusiv de strabism."}],"correct":["A","B","D"],"pages":[524],"source":"set-2"},{"id":"set2-vxAxPjxo","fingerprint":"945ceffacccb8b4f","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"Care sunt factorii cauzali ce favorizează instalarea pseudoprognatismului mandibular prin deplasarea sau poziționarea anterioară a mandibulei?","options":[{"id":"A","text":"Formarea primară a mugurilor incisivilor superiori într-o poziție palatinală."},{"id":"B","text":"Lipsa centrelor osteogenetice secundare cauzată de anodonția incisivilor laterali maxilari."},{"id":"C","text":"Deglutiția atipică însoțită de exercitarea unei presiuni linguale direct pe incisivii inferiori."},{"id":"D","text":"Lipsa abraziunii fiziologice specifice a caninilor temporari inferiori."},{"id":"E","text":"Atitudinile posturale nocturne, precum dormitul constant cu capul în hiperflexie."}],"correct":["C","D","E"],"pages":[524],"source":"set-2"},{"id":"set2-yxrATTKR","fingerprint":"2c5b8f5519c8ae9c","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"Care sunt factorii etiologici incriminați în apariția pseudoprognatismului mandibular prin modificarea axelor dentare?","options":[{"id":"A","text":"Hiperactivitatea musculaturii externe circumorale comparativ cu grupele musculare interne."},{"id":"B","text":"Decalajul temporal de erupție în care grupul incisivilor inferiori apare mult înaintea celor superiori."},{"id":"C","text":"Existența unor lucrări protetice necorespunzătoare care generează contacte premature în ocluzie."},{"id":"D","text":"Deficitul marcat de spațiu pe arcada maxilară."},{"id":"E","text":"Practicarea obiceiului vicios de succiune a degetului cu tracțiune persistentă pe incisivii inferiori."}],"correct":["B","D","E"],"pages":[525],"source":"set-2"},{"id":"set2-NjCeCSI_","fingerprint":"a1aefa4d4edd9f6b","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"Care dintre următoarele reprezintă semne clinice faciale caracteristice prognatismului mandibular anatomic?","options":[{"id":"A","text":"Etajul inferior al feței micșorat."},{"id":"B","text":"Treapta buzelor inversată, în special prin procheilie inferioară."},{"id":"C","text":"Unghiul mandibular mărit, atingând valori de 140-145°."},{"id":"D","text":"Punctul gnathion situat pe planul orbito-frontal."},{"id":"E","text":"Șanțul labio-mentonier șters."}],"correct":["B","C","E"],"pages":[525],"source":"set-2"},{"id":"set2-GxUDLr7v","fingerprint":"ca864171b397417f","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"Care aspecte definesc tabloul clinic facial în sindromul progenic prin deficit de dezvoltare a maxilarului?","options":[{"id":"A","text":"Punctul gnathion este situat anterior de planul orbito-frontal."},{"id":"B","text":"Punctul subnasale este situat posterior de planul nazo-frontal."},{"id":"C","text":"Etajul mijlociu al figurii poate fi micșorat, în special în formele grave."},{"id":"D","text":"Profilul este drept sau ușor convex."},{"id":"E","text":"Treapta buzelor este inversată, în principal prin procheilia inferioară."}],"correct":["B","C"],"pages":[525],"source":"set-2"},{"id":"set2-0m5Gq5fT","fingerprint":"40296b6f1417410b","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"Ce caracteristici clinice faciale sunt prezente în pseudo-prognatismul mandibular prin poziționarea sau deplasarea anterioară a mandibulei?","options":[{"id":"A","text":"Punctul subnasale situat pe planul Dreyfuss."},{"id":"B","text":"Etajul inferior al feței semnificativ micșorat."},{"id":"C","text":"Unghiul mandibular se menține în limite normale."},{"id":"D","text":"Punctul gnathion situat anterior față de planul Simon."},{"id":"E","text":"Treapta buzelor inversată predominant prin retrocheilie superioară."}],"correct":["A","C","D"],"pages":[526],"source":"set-2"},{"id":"set2-2495RKfA","fingerprint":"45f4bfefdb24c51c","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"Prin ce se distinge clinic pseudo-prognatismul mandibular indus de modificări ale axului dinților frontali?","options":[{"id":"A","text":"Retrocheilia superioară se corelează cu retrodenția frontală superioară."},{"id":"B","text":"Unghiul mandibular este sever mărit."},{"id":"C","text":"Treapta buzelor este ușor inversată."},{"id":"D","text":"Etajele feței rămân în limite normale."},{"id":"E","text":"Punctul gnathion depășește anterior planul Simon."}],"correct":["A","C","D"],"pages":[526],"source":"set-2"},{"id":"set2-LPA6IUAO","fingerprint":"59c43776a36f2792","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"În analiza rapoartelor faciale din anomaliile de tip progenic, ce relații ale punctelor și planurilor de referință se aplică diferitelor forme clinice?","options":[{"id":"A","text":"În prognatismul mandibular anatomic, punctul gnathion este situat anterior de planul Simon."},{"id":"B","text":"În sindromul progenic prin retrognatism maxilar, punctul gnathion se află anterior de planul orbito-frontal."},{"id":"C","text":"În forma determinată de deficitul maxilar, punctul subnasale se găsește posterior de planul nazo-frontal."},{"id":"D","text":"În prognatismul mandibular anatomic, mentonul depășește anterior planul Dreyfuss."},{"id":"E","text":"În pseudo-prognatismul mandibular funcțional, punctul subnasale se află pe planul Dreyfuss."}],"correct":["A","C","D","E"],"pages":[525],"source":"set-2"},{"id":"set2-KmabKmwX","fingerprint":"bb72f0bd97b666b3","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"Care dintre următoarele afirmații referitoare la testul de retropulsie a mandibulei în evaluarea anomaliilor de clasa a III-a sunt corecte?","options":[{"id":"A","text":"Este parțial pozitiv în pseudoprognatismul mandibular de natură articulară (cu conducere condiliană)."},{"id":"B","text":"Este pozitiv în pseudoprognatismul mandibular prin poziționarea anterioară a mandibulei de natură articulară."},{"id":"C","text":"Este pozitiv în prognatismul mandibular anatomic."},{"id":"D","text":"Este negativ în pseudoprognatismul mandibular prin deficit de dezvoltare a maxilarului superior."},{"id":"E","text":"Este negativ în pseudoprognatismul mandibular produs prin modificări de ax ale incisivilor superiori."}],"correct":["B","D","E"],"pages":[527],"source":"set-2"},{"id":"set2-zWvba2Cp","fingerprint":"3ad160013b9e2998","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"Ce modificări pot fi identificate pe teleradiografia de profil în cazul prognatismului mandibular anatomic?","options":[{"id":"A","text":"Unghiul ANB are valori crescute față de limita superioară normală de +4°."},{"id":"B","text":"Unghiul mandibular atinge valori de 140-145° datorită oblicității accentuate a ramului orizontal."},{"id":"C","text":"Unghiul lui Tweed prezintă valori mărite, fiind apreciat ca unghi de prognostic."},{"id":"D","text":"Punctul gnathion este deplasat anterior față de planul orbito-frontal."},{"id":"E","text":"Unghiul SNA prezintă valori crescute semnificativ față de normal."}],"correct":["B","C","D"],"pages":[528],"source":"set-2"},{"id":"set2-f-_N14Bn","fingerprint":"2381a6cef3cf48b7","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"Care sunt semnele clinice intraorale caracteristice prognației mandibulare adevărate?","options":[{"id":"A","text":"Se remarcă absența spațierilor între dinții temporari la nivelul arcadei superioare."},{"id":"B","text":"Arcada dento-alveolară inferioară prezintă constant o vestibulo-înclinare compensatorie."},{"id":"C","text":"Se constată prezența unor spațieri între dinții temporari inferiori, cu o localizare predilectă între canin și primul molar temporar inferior."},{"id":"D","text":"Erupția dinților frontali inferiori se produce cu mult timp înaintea celor superiori, existând un decalaj mare."},{"id":"E","text":"Forma cea mai gravă se caracterizează prin ocluzie inversă totală asociată cu inocluzie sagitală și supraocluzie frontală."}],"correct":["C","D"],"pages":[526],"source":"set-2"},{"id":"set2-6rLTZGgB","fingerprint":"45f4ca03941ed406","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CS","text":"Ce semn radiologic evaluat pe teleradiografia de profil este specific pseudoprognatismului mandibular prin deficit de dezvoltare a maxilarului?","options":[{"id":"A","text":"Punctul gnathion este situat vizibil anterior de planul orbito-frontal."},{"id":"B","text":"Unghiul SNB înregistrează valori semnificativ mărite."},{"id":"C","text":"Distanța dintre spina nazală anterioară și spina nazală posterioară este mai mică decât 7/10 din distanța N-Se."},{"id":"D","text":"Raportul dintre baza maxilarului și baza mandibulei prezintă o valoare mai mare de 2/3."},{"id":"E","text":"Unghiul SNA înregistrează valori crescute comparativ cu norma."}],"correct":["C"],"pages":[528],"source":"set-2"},{"id":"set2-7_ZOZt_g","fingerprint":"ae27e7f623929d7c","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"Ce caracteristici se asociază cu pseudoprognatismul mandibular produs prin modificarea axelor dinților frontali?","options":[{"id":"A","text":"Pe teleradiografia de profil, unghiul dintre incisivii centrali inferiori și planul bazal mandibular prezintă o valoare scăzută în prodenția incisivilor inferiori."},{"id":"B","text":"Testul de retropulsie a mandibulei indică un rezultat clinic pozitiv."},{"id":"C","text":"Apar retracții gingivale la nivelul dinților frontali inferiori pe fondul traumatismului ocluzal."},{"id":"D","text":"Unghiul dintre incisivul central superior și planul bispinos are o valoare mai mică în prezența retrodenției superioare."},{"id":"E","text":"Pe teleradiografia de profil, unghiul dintre incisivul central superior și orizontala de la Frankfurt este micșorat."}],"correct":["C","E"],"pages":[528],"source":"set-2"},{"id":"set2-4rG4jday","fingerprint":"64b2fb263d9991da","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"Care sunt consecințele funcționale și morfologice recunoscute ca fiind generate de anomalia de clasa a III-a?","options":[{"id":"A","text":"Funcția fonetică se modifică ca urmare a retrodenției structurilor linguale spre peretele posterior faringian în timpul actului fonator."},{"id":"B","text":"Lipsa stimulului funcțional are drept consecință exclusivă remanierea cavității glenoide, conservând structurile parodonțiului marginal."},{"id":"C","text":"Funcția de deglutiție este modificată din cauza comportamentului atipic al limbii."},{"id":"D","text":"Funcția masticatorie suferă o alterare gravă secundară reducerii câmpului masticator și apariției blocajelor ocluzo-articulare."},{"id":"E","text":"Funcția fizionomică rămâne intactă în ciuda apariției blocajelor dento-maxilare precoce."}],"correct":["C","D"],"pages":[528],"source":"set-2"},{"id":"set2-BJimoJcS","fingerprint":"8af2a48614d1c4e4","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CS","text":"Care formă clinică a anomaliei de clasa a III-a are un prognostic favorabil, permițând corectarea spontană prin îndepărtarea factorilor cauzali?","options":[{"id":"A","text":"Pseudoprognatismul prin conducere condiliană în stadiu incipient"},{"id":"B","text":"Prognatismul mandibular anatomic"},{"id":"C","text":"Angrenajul invers cu modificări morfologice"},{"id":"D","text":"Sindromul progenic cu direcție de creștere verticală facială"},{"id":"E","text":"Forma funcțională anatomizată"}],"correct":["A"],"pages":[529],"source":"set-2"},{"id":"set2-EkJF8-_a","fingerprint":"d7384b55a6f9028d","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"Care sunt aspectele care determină un prognostic nefavorabil în cazul sindromului progenic în perioada post-pubertară?","options":[{"id":"A","text":"Lipsa dezvoltării maxilarului"},{"id":"B","text":"Corectarea spontană a discrepanței scheletice odată cu oprirea creșterii"},{"id":"C","text":"Direcția de creștere orizontală facială în perioada adolescenței timpurii"},{"id":"D","text":"O direcție de creștere verticală facială în perioada adolescenței târzii"},{"id":"E","text":"O perioadă mai mare de creștere a mandibulei"}],"correct":["A","D","E"],"pages":[529],"source":"set-2"},{"id":"set2-SemCx7g7","fingerprint":"5cde3e7a24b16a51","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"Care sunt caracteristicile evolutive și terapeutice ale anomaliilor de clasa a III-a?","options":[{"id":"A","text":"Intervenția terapeutică este recomandată doar începând de la erupția dentiției definitive."},{"id":"B","text":"Cartilajul condilian de creștere poate rămâne activ timp îndelungat, predispunând la recidivă posttratament ortodontic."},{"id":"C","text":"Tratamentul ortopedic interceptiv are un prognostic favorabil dacă este administrat înainte de puseul de creștere pubertar."},{"id":"D","text":"Modificările dentare și agravarea discrepanței scheletice au loc în exclusivitate în perioada prepubertară."},{"id":"E","text":"Tiparul scheletic se conturează predominant prepubertar."}],"correct":["B","C","E"],"pages":[529],"source":"set-2"},{"id":"set2-5DmXGR7D","fingerprint":"a0230f3b4db6a7d2","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CS","text":"Ce caracteristică a cartilajului condilian de creștere predispune la apariția recidivei posttratament ortodontic la pacienții cu anomalii de clasa a III-a?","options":[{"id":"A","text":"Pierderea capacității de reglare a cantității de creștere a maxilarului."},{"id":"B","text":"Degenerarea sa precoce înainte de vârsta de 21 de ani."},{"id":"C","text":"Transformarea sa în os spongios la finalul perioadei prepubertare."},{"id":"D","text":"Rămâne activ timp îndelungat sau își reia activitatea la vârsta adultă."},{"id":"E","text":"Își încetează activitatea definitiv la instalarea dentiției permanente."}],"correct":["D"],"pages":[529],"source":"set-2"},{"id":"set2-VFF35zrr","fingerprint":"f8b97ee41c4fdc23","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"Care dintre următorii factori sunt asociați cu un prognostic bun al terapiei precoce la pacienții cu anomalii de clasa a III-a?","options":[{"id":"A","text":"Prezența prognatismului mandibular anatomic."},{"id":"B","text":"Lipsa unui istoric familial privind anomalia."},{"id":"C","text":"Existența unei discrepanțe scheletice majore."},{"id":"D","text":"Tiparul de creștere facial convergent."},{"id":"E","text":"Creșterea condiliană simetrică."}],"correct":["B","D","E"],"pages":[530],"source":"set-2"},{"id":"set2-Xjq4DKdX","fingerprint":"49ba11995ae0cb85","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CS","text":"Care afirmație referitoare la tratamentul ortodontic al pacienților cu anomalii de clasa a III-a este corectă?","options":[{"id":"A","text":"Pentru prognatismul mandibular anatomic se contraindică utilizarea tracțiunii extraorale vertex-menton în dentiția temporară."},{"id":"B","text":"Radiografiile panoramice seriate reprezintă metoda de elecție pentru a determina dacă creșterea feței s-a oprit."},{"id":"C","text":"La pacienții cu prognatism mandibular anatomic, tratamentul ortodontic este recomandat a se realiza la vârsta adultă, după încheierea creșterii."},{"id":"D","text":"Tiparul de creștere individual al mandibulei poate fi modificat definitiv printr-un tratament ortodontic inițiat timpuriu."},{"id":"E","text":"Tratamentul curativ timpuriu are o eficiență redusă din cauza plasticității osoase caracteristice stadiilor incipiente."}],"correct":["C"],"pages":[531],"source":"set-2"},{"id":"set2-5WNWhHwy","fingerprint":"7fa201cdbb03edca","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"Dintre măsurile specifice ce vizează tratamentul profilactic și interceptiv al sindromului progenic fac parte:","options":[{"id":"A","text":"Extracția dinților temporari care persistă peste vârsta normală de permutare dentară."},{"id":"B","text":"Corectarea succiunii degetelor cu presiune oro-vestibulară asupra incisivililor superiori."},{"id":"C","text":"Desființarea contactelor premature prin șlefuiri selective ale caninilor temporari inferiori neabrazați."},{"id":"D","text":"Prevenirea și corectarea ticului de retrudare a mandibulei."},{"id":"E","text":"Supravegherea diastemizării fiziologice și a procesului de abraziune a dinților temporari."}],"correct":["A","C","E"],"pages":[529],"source":"set-2"},{"id":"set2-HuVfVkjX","fingerprint":"e81fbf17e5c69f5c","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CM","text":"Care dintre următoarele afirmații referitoare la mijloacele și obiectivele tratamentului curativ al sindromului progenic sunt adevărate?","options":[{"id":"A","text":"Bărbița cu capelină reprezintă mijlocul terapeutic de elecție pentru stimularea exclusivă a dezvoltării maxilarului."},{"id":"B","text":"Obținerea unei supraocluzii frontale acționează ca o contenție naturală, contribuind la menținerea rezultatelor în timp."},{"id":"C","text":"Masca Delaire prezintă o componentă terapeutică de limitare, frânare sau repoziționare mandibulară prin intermediul pelotei mentoniere."},{"id":"D","text":"Armonizarea echilibrului între cele două arcade se poate realiza prin limitarea creșterii mandibulare."},{"id":"E","text":"Tratamentul anomaliilor de clasa a III-a prezintă un potențial scăzut de recidivă după obținerea rapoartelor de ocluzie funcționale."}],"correct":["B","C","D"],"pages":[530],"source":"set-2"},{"id":"set2-y5Hf71iL","fingerprint":"9b7e7f90f47ff0df","chapterId":"set-2","subchapterId":"set2-6.2.4","type":"CS","text":"Pentru ce forme clinice ale sindromului progenic este indicat tratamentul exclusiv ortodontico-chirurgical, luând în considerare limitările abordării exclusiv conservatoare?","options":[{"id":"A","text":"Anomalii de clasa a III-a însoțite de un tipar de creștere facial convergent și discrepanță scheletică minimă."},{"id":"B","text":"Prognatism mandibular la pacienți cu absența unui istoric familial marcat și cu estetică facială inițială bună."},{"id":"C","text":"Anomalii depistate în formă incipientă, unde gradul optim de plasticitate osoasă ajută mecanica ortodontică."},{"id":"D","text":"Pseudoprognatism prin retrognatism maxilar asociat cu decalaje scheletale mandibulo-maxilare semnificative."},{"id":"E","text":"Prognatism mandibular funcțional în perioada pubertară la pacienți aflați în puseu de creștere."}],"correct":["D"],"pages":[531],"source":"set-2"}];
